package database

// The two generated sim/core files. A row the generator could not express keeps
// its place as a commented shell naming the reason, the same idiom the on-use
// effects file uses, so a reader of the generated file sees every manifest row.

const tmplStrBuffRows = `
{{- range .Rows}}

{{if .Supported}}
{{if .HasWowhead}}// {{.Label}} - https://www.wowhead.com/forever/spell={{.SpellID}}{{end}}
{{- if .Note}}
// {{.Note}}
{{- end}}
{{- if .CategoryVar}}
var {{.CategoryVar}} = "{{.Category}}"
{{- end}}
{{- if .HasValue}}
func {{.Go}}Value(talentPoints int32) float64 {
	return {{.ValueExpr}}
}
{{- end}}
func {{.Go}}Duration(talentPoints int32) time.Duration {
	return {{.Duration}}
}
{{- if .HasCooldown}}
func {{.Go}}Cooldown() time.Duration {
	return {{.Cooldown}}
}
{{- end}}
func {{.Go}}Aura(unit *Unit, isPlayer bool, talentPoints int32{{.ExtraParams}}) *Aura {
	{{.Constructor}}
}
{{- else}}
{{if .HasWowhead}}// {{.Label}} - https://www.wowhead.com/forever/spell={{.SpellID}}
{{end}}// func {{.Go}}Aura(unit *Unit, isPlayer bool, talentPoints int32{{.ExtraParams}}) *Aura // {{.Field}}, {{.Kind}}: {{.Reason}}
{{- end}}
{{- end}}
`

const TmplStrBuffs = `// Code generated by tools/database/gen_spelldata. DO NOT EDIT.

package core

import (
{{- if .NeedsTime}}
	"time"

{{ end }}
	"github.com/wowsims/forever/sim/core/proto"
{{- if .NeedsStats}}
	"github.com/wowsims/forever/sim/core/stats"
{{- end}}
)
` + tmplStrBuffRows + `
func applyGeneratedBuffs(char *Character, raid *proto.RaidBuffs, party *proto.PartyBuffs, individual *proto.IndividualBuffs) {
{{- range .Rows}}
{{- if and .Supported .HasApply}}
	if {{.ApplyIf}} {
		{{.ApplyBody}}
	}
{{- end}}
{{- end}}
}
`

const TmplStrDebuffs = `// Code generated by tools/database/gen_spelldata. DO NOT EDIT.

package core

import (
{{- if .NeedsTime}}
	"time"

{{ end }}
	"github.com/wowsims/forever/sim/core/proto"
{{- if .NeedsStats}}
	"github.com/wowsims/forever/sim/core/stats"
{{- end}}
)
` + tmplStrBuffRows + `
func applyGeneratedDebuffs(target *Unit, debuffs *proto.Debuffs, raid *proto.Raid) {
{{- range .Rows}}
{{- if and .Supported .HasApply}}
	if {{.ApplyIf}} {
		{{.ApplyBody}}
	}
{{- end}}
{{- end}}
}
`
